// Deterministic maths for the simulation: integer square root, fixed-point helpers and a Q15 sin/cos table.
// Only exactly-rounded operations are used (+ - * /, Math.sqrt, Math.floor, integer shifts); the table is generated by
// tools/gen/lut.ts (which may use Math.sin) and committed as src/sim/sinLut.ts.
import { SIN_QUARTER_Q15, SIN_QUARTER_STEPS } from './sinLut';

/** 1.0 in Q15 fixed point. */
export const Q15_ONE = 32768;
/** Q15 shift. */
export const Q15_SHIFT = 15;
/** Angles are unsigned 16-bit fractions of a full turn: 65536 = 360 degrees. */
export const ANGLE_TURN = 65536;
/** A quarter turn (90 degrees) in angle units. */
export const ANGLE_QUARTER = 16384;

/** Largest n that isqrt() accepts exactly (2^52): above it the square of the root may leave the safe integer range. */
export const ISQRT_MAX = 4503599627370496;

/** Floor of the square root of an unsigned 32-bit integer, by the bitwise digit method (no floating point at all). */
export function isqrt32(n: number): number {
  let x = n >>> 0;
  let res = 0;
  let bit = 1 << 30;
  while (bit > x) bit >>= 2;
  while (bit !== 0) {
    if (x >= res + bit) {
      x -= res + bit;
      res = (res >> 1) + bit;
    } else {
      res >>= 1;
    }
    bit >>= 2;
  }
  return res;
}

/**
 * Floor of the square root of an integer in [0, ISQRT_MAX]. Math.sqrt is exactly rounded (IEEE 754), the integer
 * correction loops make the result exact whatever the rounding did. Below 0 gives 0, above ISQRT_MAX it is clamped.
 */
export function isqrt(n: number): number {
  const v = n >= ISQRT_MAX ? ISQRT_MAX : Math.floor(n);
  if (!(v > 0)) return 0;
  let r = Math.floor(Math.sqrt(v));
  while (r * r > v) r--;
  while ((r + 1) * (r + 1) <= v) r++;
  return r;
}

/** Floor division of two integers, exact for any operands that are safe integers (no rounding of the quotient). */
export function floorDiv(n: number, d: number): number {
  const r = n % d;
  const q = (n - r) / d;
  return r !== 0 && (r < 0) !== (d < 0) ? q - 1 : q;
}

/** Clamps v into [lo, hi]. */
export function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

/** Q15 times Q15, rounded half up. Both factors must lie in [-32768, 32768] so that the product fits 31 bits. */
export function mulQ15(a: number, b: number): number {
  return (a * b + 16384) >> 15;
}

/** An integer v scaled by a Q15 factor q, rounded half up; exact while |v * q| < 2^53. */
export function scaleQ15(v: number, q: number): number {
  return Math.floor((v * q + 16384) / 32768);
}

/** a / b as Q15 for integers a and b > 0 (rounded half up); exact while |a| < 2^37. */
export function divQ15(a: number, b: number): number {
  return floorDiv(a * 32768 + (b >> 1), b);
}

/** Value of the full-circle sine table at index i (4096 steps per turn), in Q15. */
function sineAtIndex(i: number): number {
  const k = i & (SIN_QUARTER_STEPS * 4 - 1);
  const quadrant = Math.floor(k / SIN_QUARTER_STEPS);
  const j = k & (SIN_QUARTER_STEPS - 1);
  switch (quadrant) {
    case 0:
      return SIN_QUARTER_Q15[j] as number;
    case 1:
      return SIN_QUARTER_Q15[SIN_QUARTER_STEPS - j] as number;
    case 2:
      return 0 - (SIN_QUARTER_Q15[j] as number); // 0 - x, not -x: negating the table's 0 would give -0
    default:
      return 0 - (SIN_QUARTER_Q15[SIN_QUARTER_STEPS - j] as number);
  }
}

/**
 * Sine of an angle (unsigned 16-bit turn fraction, wraps) as Q15 in [-32768, 32768]. The table has 4096 steps per
 * turn; the 4 low bits of the angle interpolate linearly. Error against the true sine is at most 1 unit of Q15.
 */
export function sinQ15(angle: number): number {
  const a = angle & 0xffff;
  const i = a >> 4;
  const frac = a & 15;
  const v0 = sineAtIndex(i);
  if (frac === 0) return v0;
  const v1 = sineAtIndex(i + 1);
  return v0 + (((v1 - v0) * frac + 8) >> 4);
}

/** Cosine of an angle (see sinQ15) as Q15. */
export function cosQ15(angle: number): number {
  return sinQ15(angle + ANGLE_QUARTER);
}
